/// Request and connection values expected in the durable dispatch record.
struct NativeDispatchIdentity<'a> {
    payload_digest: Digest32,
    request_digest: Digest32,
    source_admission_digest: Digest32,
    codex_home_digest: Digest32,
    connection_id: u64,
    session_id: &'a str,
    deadline_ms: u64,
}

/// Claimed authority frontier and witness expected in the durable dispatch.
struct NativeDispatchAuthority<'a> {
    authority_epoch: u64,
    revocation_revision: u64,
    revocation_head_digest: &'a str,
    authority_witness: &'a str,
}

fn verify_persisted_dispatch_binding(
    control: &DurableInferenceControl,
    request_id: &str,
    identity: NativeDispatchIdentity<'_>,
    authority: NativeDispatchAuthority<'_>,
    app_server_version: &str,
) -> Result<()> {
    let NativeDispatchIdentity {
        payload_digest,
        request_digest,
        source_admission_digest,
        codex_home_digest,
        connection_id,
        session_id,
        deadline_ms,
    } = identity;
    let NativeDispatchAuthority {
        authority_epoch,
        revocation_revision,
        revocation_head_digest,
        authority_witness,
    } = authority;

